entries[35222] = { ["name"] = "Shipment of Animal Parts", ["text"] = "Quest Item\n\"Filled with skins, furs, bones, and anything else of value that might come from an animal.\"" }
entries[35223] = { ["name"] = "Papa Hummel's Old-Fashioned Pet Biscuit", ["text"] = "Binds when picked up\nUse: Doubles a targeted Non-Combat Pet's size for as long as it remains at its master's side." }
