entries[35225] = { ["name"] = "X-51 Nether-Rocket", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 60\nRequires Riding (225)\nUse: Teaches you how to summon this mount. Can only be used in Outland or Northrend.\nA riding rocket! This can only be summoned in Outland or Northrend." }
entries[35226] = { ["name"] = "X-51 Nether-Rocket X-TREME", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 70\nRequires Riding (300)\nUse: Teaches you how to summon this mount. This is a very fast mount.\nAn X-TREME riding rocket! This is a very fast mount." }
entries[35227] = { ["name"] = "Goblin Weather Machine - Prototype 01-B", ["text"] = "Binds when picked up\nToy\nUse: Right Click to activate your Personal Weather Maker. (30 Sec Cooldown)" }
