entries[35237] = { ["name"] = "Orb of the Crawler", ["text"] = "Quest Item\nUnique\nUse: Transforms you into an innocent crab for 3 min. It can only be used upon the Zoram Strand of Ashenvale. Only the new Twlight Cultists and their allies will be fooled. Looting, taking a hostile action, or casting beneficial spells will drop the disguise." }
