entries[35294] = { ["name"] = "Recipe: Elixir of Empowerment", ["text"] = "Binds when picked up\nRequires Alchemy (365)\nUse: Teaches you how to make an Elixir of Empowerment.\nSell Price: 2 50\nElixir of Empowerment\nRequires Level 60\nUse: Decreases the magical resistances of your spell targets by 30 for 1 hour. Guardian Elixir. (3 Sec Cooldown)\nSell Price: 70\nRequires Netherbloom , Mana Thistle , Imbued Vial" }
entries[35295] = { ["name"] = "Recipe: Haste Potion", ["text"] = "Binds when picked up\nRequires Alchemy (350)\nUse: Teaches you how to make a Haste Potion.\nSell Price: 2\nHaste Potion\nRequires Level 60\nUse: Increases haste rating by 400 for 15 sec. (1 Min Cooldown)\nSell Price: 50\nRequires Terocone (2), Netherbloom , Imbued Vial" }
entries[35296] = { ["name"] = "Plans: Adamantite Weapon Chain", ["text"] = "Binds when picked up\nRequires Blacksmithing (335)\nUse: Teaches you how to make an Adamantite Weapon Chain.\nSell Price: 9 50\nAdamantite Weapon Chain\nRequires Level 50\nUse: Attaches a chain to your weapon, reducing the duration of Disarm effects by 50% and increasing your Parry rating by 15. Does not stack with other similar effects.\n\nAttaching an adamantite weapon chain causes the item to become soulbound.\nSell Price: 1 80\nRequires Hardened Adamantite Bar (2), Khorium Bar" }
entries[35297] = { ["name"] = "Formula: Enchant Boots - Boar's Speed", ["text"] = "Binds when picked up\nRequires Enchanting (360)\nUse: Teaches you how to permanently enchant boots to give a minor movement speed increase and increase Stamina by 9. Requires a level 35 or higher item.\nPermanently enchant boots to give a minor movement speed increase and increase Stamina by 9. Requires a level 35 or higher item.\nSell Price: 3" }
